from cyclopts import App

app = App()


@app.default
def status():
    """Show current status."""
    print("Status: Running")


@app.command
def start():
    """Start the service."""
    print("Service started")


@app.command
def stop():
    """Stop the service."""
    print("Service stopped")


if __name__ == "__main__":
    app()
